// Checkout conversion module - tracks paid events and fixes revenue tracking
const fs = require('fs');
const path = require('path');

const CONVERSION_LOG = path.join(__dirname, '..', 'data', 'conversion_events.log');

function ensureLogDir() {
  const dir = path.dirname(CONVERSION_LOG);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function logConversion(event) {
  ensureLogDir();
  const entry = {
    ts: new Date().toISOString(),
    event: event,
    paid: true
  };
  fs.appendFileSync(CONVERSION_LOG, JSON.stringify(entry) + '\n');
  return entry;
}

function getConversionCount() {
  ensureLogDir();
  if (!fs.existsSync(CONVERSION_LOG)) return 0;
  const lines = fs.readFileSync(CONVERSION_LOG, 'utf-8').trim().split('\n').filter(l => l);
  return lines.length;
}

function getConversionRate(leads) {
  const conversions = getConversionCount();
  if (leads === 0) return 0;
  return (conversions / leads) * 100;
}

module.exports = { logConversion, getConversionCount, getConversionRate };
